public class BankAccount {
    private String owner;
    private double balance;
    public BankAccount(String owner,double initial){ this.owner=owner; this.balance=initial; }
    public void deposit(double amt){ if(amt<=0) throw new IllegalArgumentException("Must be positive"); balance+=amt; }
    public boolean withdraw(double amt){ if(amt>balance) return false; balance-=amt; return true; }
    public double getBalance(){ return balance; }
}

public class Main{
    public static void main(String[] args){
        BankAccount alice = new BankAccount("Alice",1000.0);
        alice.deposit(250);
        alice.withdraw(100);
        System.out.println(alice.getBalance());
    }
}

